// one connection sends, waits, records, then sends the next
fun closedLoop(client: Client, ratePerSecond: Int, durationNanos: Long, histogram: LogHistogram) {
    val interval = 1_000_000_000L / ratePerSecond
    val end = System.nanoTime() + durationNanos
    var slot = System.nanoTime()
    while (slot < end) {
        LockSupport.parkNanos(slot - System.nanoTime())      // wait for the slot (no wait if late)
        val sentAt = System.nanoTime()
        client.authorize()                                    // blocks while the server is stuck
        histogram.record((System.nanoTime() - sentAt) / 1_000)   // µs from the ACTUAL send
        slot += interval
    }
}

