// requests go out on schedule, whatever the server is doing
fun openLoop(client: Client, ratePerSecond: Int, durationNanos: Long, histogram: LogHistogram) {
    val interval = 1_000_000_000L / ratePerSecond
    val end = System.nanoTime() + durationNanos
    Executors.newVirtualThreadPerTaskExecutor().use { pool ->
        var slot = System.nanoTime()
        while (slot < end) {
            LockSupport.parkNanos(slot - System.nanoTime())
            val scheduledAt = slot
            pool.execute {
                client.authorize()                            // later requests don't wait for this one
                synchronized(histogram) { histogram.record((System.nanoTime() - scheduledAt) / 1_000) }  // µs from the PLANNED send
            }
            slot += interval
        }
    }
}
